from solution import check_value


def test_issue_exact_example():
    """Example assert check_value({...12...},10)==False."""
    data = {'Cierra Vega': 12, 'Alden Cantrell': 12, 'Kierra Gentry': 12, 'Pierre Cox': 12}
    assert check_value(data, 10) == False  # 12 != 10 so False


def test_issue_all_equal_n():
    """Check if all values are same in a dictionary returns True when all equal n."""
    data = {'a': 10, 'b': 10, 'c': 10}
    assert check_value(data, 10) == True  # 10 == 10 and 10 == 10 so True


def test_issue_all_same_but_not_n():
    """Check if all values are same in a dictionary returns False when uniform but not n."""
    data = {'a': 12, 'b': 12}
    assert check_value(data, 10) == False  # 12 != 10 so False


def test_issue_single_matching():
    """Check if all values are same in a dictionary with one matching value is True."""
    data = {'only': 7}
    assert check_value(data, 7) == True  # 7 == 7 so True


def test_issue_single_mismatching():
    """Check if all values are same in a dictionary with one differing value is False."""
    data = {'only': 7}
    assert check_value(data, 8) == False  # 7 != 8 so False


def test_issue_one_mismatch_among_many():
    """Check if all values are same in a dictionary fails if one value differs."""
    data = {'a': 10, 'b': 10, 'c': 11}
    assert check_value(data, 10) == False  # 11 != 10 so False


def test_issue_value_just_below_n():
    """Check if all values are same in a dictionary with values just below n is False."""
    data = {'a': 9, 'b': 9}
    assert check_value(data, 10) == False  # 9 != 10 (10 - 1 = 9) so False


def test_issue_value_just_above_n():
    """Check if all values are same in a dictionary with values just above n is False."""
    data = {'a': 11}
    assert check_value(data, 10) == False  # 11 != 10 (10 + 1 = 11) so False


def test_issue_empty_dict():
    """Check if all values are same in a dictionary vacuously holds for empty dict."""
    data = {}
    assert check_value(data, 10) == True  # no elements to differ, all() is True


def test_contract_true_is_bool():
    """Check if all values are same in a dictionary returns bool True object."""
    result = check_value({'x': 3}, 3)
    assert result is True  # 3 == 3 so True


def test_contract_false_is_bool():
    """Check if all values are same in a dictionary returns bool False object."""
    result = check_value({'x': 3}, 4)
    assert result is False  # 3 != 4 so False


def test_contract_does_not_mutate():
    """Check if all values are same in a dictionary does not mutate input."""
    data = {'k1': 5, 'k2': 5}
    check_value(data, 5)  # 5 == 5 so True, no mutation
    assert data == {'k1': 5, 'k2': 5}  # 5 + 0 = 5 unchanged
